import asyncio
import copy
import importlib.util
import json
from pathlib import Path

import httpx
import pytest

spec=importlib.util.spec_from_file_location('manual116','/tmp/wisp116_live.py')
r=importlib.util.module_from_spec(spec);spec.loader.exec_module(r)

@pytest.fixture
def manifest(tmp_path):
    return r.freeze(Path('/tmp/wisp116-dryrun.json'),tmp_path/'manifest.json')


def test_frozen_exact_settings_sources_and_counterbalance(manifest):
    assert len(manifest['attempts'])==48
    for i in range(0,24,2):
        a,b=manifest['attempts'][i:i+2]
        c,d=manifest['attempts'][i+24:i+26]
        assert a['variant']==d['variant'] and b['variant']==c['variant']
        assert a['payload']['messages'][1:]==b['payload']['messages'][1:]
        assert a['payload']['store'] is a['payload']['stream'] is False
    r.check_manifest(manifest,r.sha(r.encoded(manifest)))


def test_all_failures_count_and_durable_reservation_no_retry(manifest,tmp_path):
    path=tmp_path/'ledger.json';seen=[]
    def handler(request):
        ledger=json.loads(path.read_bytes());attempt=manifest['attempts'][len(seen)]
        assert len(ledger['attempts'])==len(seen)+1
        assert ledger['reserved_output_tokens']==(len(seen)+1)*4096
        assert ledger['attempts'][-1]['status']=='attempt_reserved'
        assert str(request.url)==r.ENDPOINT
        assert request.content==r.encoded(attempt['payload'])
        seen.append(attempt['id'])
        if len(seen)%3==0: raise httpx.ReadTimeout('private upstream must not be logged',request=request)
        return httpx.Response(429,content=b'private upstream body must not be stored')
    async def execute():
        async with httpx.AsyncClient(transport=httpx.MockTransport(handler),trust_env=False,follow_redirects=False) as client:
            result=await r.run(manifest,r.sha(r.encoded(manifest)),path,client,'fake-test-key')
            with pytest.raises(AssertionError):
                await r.run(manifest,r.sha(r.encoded(manifest)),path,client,'fake-test-key')
        return result
    result=asyncio.run(execute())
    assert len(seen)==len(set(seen))==48
    assert result['reserved_output_tokens']==196608
    assert all(a['status'] in ('http_error','transport_or_invalid_envelope') for a in result['attempts'])
    assert b'private' not in path.read_bytes() and b'fake-test-key' not in path.read_bytes()

@pytest.mark.parametrize('mutation',['endpoint','payload','store','cap','count','sources'])
def test_tamper_before_send(manifest,tmp_path,mutation):
    approved=r.sha(r.encoded(manifest));calls=[]
    if mutation=='endpoint': manifest['endpoint']='https://elsewhere.invalid/v1/chat/completions'
    elif mutation=='payload': manifest['attempts'][0]['payload']['messages'][-1]['content']='changed'
    elif mutation=='store': manifest['attempts'][0]['payload']['store']=True
    elif mutation=='cap': manifest['max_reserved_output_tokens']=196609
    elif mutation=='count': manifest['attempts'].append(copy.deepcopy(manifest['attempts'][0]))
    else: manifest['source_digests']['api/dispatch.py']='bad'
    async def execute():
        async with httpx.AsyncClient(transport=httpx.MockTransport(lambda q:calls.append(q)),trust_env=False) as client:
            with pytest.raises(AssertionError):
                await r.run(manifest,approved,tmp_path/'ledger.json',client,'fake')
    asyncio.run(execute());assert calls==[]


def test_raw_fail_separate_from_production_and_safe_usage(manifest):
    text='{"text":"ok","appraisal":{"category":"neutral","intensity":"low","confidence":"clear"},"decision":{"behavior":"respond"}}'
    errors,parsed=r.raw_check(text,manifest['attempts'][0])
    assert errors==['invalid_raw_decision'] and 'decision' not in parsed
    assert r.clean_usage({'prompt_tokens':12,'private':'SECRET','completion_tokens_details':{'reasoning_tokens':2,'private':'SECRET'}})=={'prompt_tokens':12,'completion_tokens':None,'total_tokens':None,'completion_tokens_details':{'reasoning_tokens':2}}

@pytest.mark.parametrize('kind',['success','redirect','oversize','bad_data','bad_choice','bad_message'])
def test_envelopes_success_and_redirect_never_followed(manifest,tmp_path,kind):
    seen=[];ledger_path=tmp_path/'ledger.json'
    text='{"text":"ok","appraisal":{"category":"neutral","intensity":"low","confidence":"clear"}}'
    def handler(request):
        seen.append(request)
        if kind=='redirect': return httpx.Response(302,headers={'Location':'https://evil.invalid/'})
        if kind=='oversize': return httpx.Response(200,content=b'x'*262145)
        if kind=='bad_data': return httpx.Response(200,json=[])
        if kind=='bad_choice': return httpx.Response(200,json={'choices':[None]})
        if kind=='bad_message': return httpx.Response(200,json={'choices':[{'message':None}]})
        return httpx.Response(200,json={'choices':[{'finish_reason':'stop','message':{'content':text}}], 'usage':{'prompt_tokens':1,'completion_tokens':1,'total_tokens':2}})
    async def execute():
        async with httpx.AsyncClient(transport=httpx.MockTransport(handler),trust_env=False,follow_redirects=False) as client:
            return await r.run(manifest,r.sha(r.encoded(manifest)),ledger_path,client,'fake')
    result=asyncio.run(execute())
    assert len(seen)==48
    assert all(str(q.url)==r.ENDPOINT for q in seen)
    if kind=='success':
        assert all(a['status']=='ok' and a['raw_errors']==[] and a['production_response']['text']=='ok' for a in result['attempts'])
    else:
        assert all(a['status']!='ok' for a in result['attempts'])


